from __future__ import annotations

import base64
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

SETTINGS_ZLIB_B64 = """"""

settings = zlib.decompress(base64.b64decode(SETTINGS_ZLIB_B64)).decode("utf-8")
if "Cloudflare Bağlantısı" not in settings or "WhatsApp / Meta Bağlantısı" not in settings:
    raise SystemExit("Decoded Settings UI is incomplete")
(ROOT / "src/frontend/pages/settings.tsx").write_text(settings, "utf-8")

api_path = ROOT / "src/frontend/api.ts"
api = api_path.read_text("utf-8")
old = "if (!navigator.onLine) throw new Error('Çevrimdışı modda yalnız yerel onaylı bilgi araması kullanılabilir.');"
new = "if (!navigator.onLine) throw new Error('İnternet bağlantısı yok. Bulut işlemleri geçici olarak kullanılamıyor.');"
if old in api:
    api = api.replace(old, new, 1)
api_path.write_text(api, "utf-8")

pages_path = ROOT / "src/frontend/pages/index.ts"
pages = pages_path.read_text("utf-8")
pages = pages.replace("export { DesktopIndexPanel } from './desktopIndex';\n", "")
pages_path.write_text(pages, "utf-8")

readme_path = ROOT / "README.md"
readme = readme_path.read_text("utf-8")
start = readme.find("## Çevrimdışı Windows modu")
end = readme.find("## 500 maddelik şartname kanıtı", start)
if start >= 0 and end > start:
    replacement = """## Windows bağlantı yönetimi

Cloudflare ve WhatsApp/Meta bağlantıları yalnız **Ayarlar → Bağlantılar** bölümünden kullanıcı tarafından kurulur. Doğrulanan Cloudflare bağlantısı Windows Credential Manager'da saklanır ve uygulama kapatılıp açıldığında **Bağlı** görünmeye devam eder. Aynı bölümden bağlantı doğrulanabilir, bağlantı bilgisi güncellenebilir veya bağlantı kaldırılabilir. Bağlantıyı kaldırmak D1, R2, müşteri kayıtları ya da konuşma geçmişini silmez.

İnternet kesildiğinde uygulama teknik FAISS, checksum veya yerel indeks ekranı açmaz. Kayıtlı bağlantı korunur; bulut gerektiren işlemler internet yeniden gelene kadar kullanılamaz.

"""
    readme = readme[:start] + replacement + readme[end:]
readme_path.write_text(readme, "utf-8")

app = (ROOT / "src/frontend/App.tsx").read_text("utf-8")
for forbidden in ("Yerel Bilgi Modu", "OfflineDesktopPage", "phase: 'offline'", "Cloudflare Kurulumu ve Onarımı"):
    if forbidden in app:
        raise SystemExit(f"Superseded flow remains in App.tsx: {forbidden}")
for required in ("DesktopConnectionsPage", "phase: 'connections'", "Bağlantıyı Kaldır"):
    if required not in app:
        raise SystemExit(f"Required connection flow missing from App.tsx: {required}")

print("Settings-only Cloudflare and Meta connection flow applied.")
